.darma-loader-darma-b13-spider-web-weave { --accent: var(--loader-color, #e2e8f0); --accent-2: var(--loader-secondary-color, #64748b); width: var(--loader-size, 108px); height: var(--loader-size, 108px); position: relative; }
.darma-loader-darma-b13-spider-web-weave::before { content: ''; position: absolute; inset: 0; border-radius: 50%; background: repeating-conic-gradient(from 0deg, var(--accent-2) 0 .7deg, transparent .7deg 45deg); }
.darma-loader-darma-b13-spider-web-weave::after { content: ''; position: absolute; inset: 0; border-radius: 50%; background: repeating-radial-gradient(circle, transparent 0 10.5%, var(--accent) 10.5% 12%); animation: darma-loader-darma-b13-spider-web-weave-weave calc(var(--loader-speed, 1s) * 2.6) linear infinite; }
.darma-loader-darma-b13-spider-web-weave span { position: absolute; z-index: 2; top: 50%; left: 50%; width: 11%; height: 11%; margin: -5.5% 0 0 -5.5%; border-radius: 50%; background: radial-gradient(circle at 42% 34%, color-mix(in srgb, #fff 30%, var(--accent-2)), color-mix(in srgb, #000 42%, var(--accent-2))); animation: darma-loader-darma-b13-spider-web-weave-crawl calc(var(--loader-speed, 1s) * 2.6) linear infinite; }
@keyframes darma-loader-darma-b13-spider-web-weave-weave { 0% { clip-path: circle(5% at 50% 50%); } 100% { clip-path: circle(51% at 50% 50%); } }
@keyframes darma-loader-darma-b13-spider-web-weave-crawl { 0% { transform: rotate(0deg) translateX(calc(var(--loader-size, 108px) * .04)); } 100% { transform: rotate(1080deg) translateX(calc(var(--loader-size, 108px) * .45)); } }

